const ONBELLEK_ADI = "servis-takip-v1";

// App pages relative to the service worker's scope (works under any basePath).
const ONBELLEK_SAYFALARI = [
  "./",
  "./kayit/",
  "./arac/",
  "./arac/detay/",
  "./arac/duzenle/",
  "./hatirlatma/",
  "./yedek/",
  "./kullanim/",
];

// Static RSC payload files generated by `next build` (`output: "export"`,
// `trailingSlash: true`) for client-side Link transitions.
const EK_ONBELLEK_DOSYALARI = [
  "./manifest.webmanifest",
  "./icons/icon.svg",
  "./index.txt",
  "./__next._tree.txt",
  "./__next._full.txt",
  "./__next.__PAGE__.txt",
  "./kayit/index.txt",
  "./kayit/__next._tree.txt",
  "./kayit/__next._full.txt",
  "./kayit/__next.kayit.__PAGE__.txt",
  "./arac/index.txt",
  "./arac/__next._tree.txt",
  "./arac/__next._full.txt",
  "./arac/__next.arac.__PAGE__.txt",
  "./arac/detay/index.txt",
  "./arac/detay/__next._tree.txt",
  "./arac/detay/__next._full.txt",
  "./arac/detay/__next.arac.detay.__PAGE__.txt",
  "./arac/duzenle/index.txt",
  "./arac/duzenle/__next._tree.txt",
  "./arac/duzenle/__next._full.txt",
  "./arac/duzenle/__next.arac.duzenle.__PAGE__.txt",
  "./hatirlatma/index.txt",
  "./hatirlatma/__next._tree.txt",
  "./hatirlatma/__next._full.txt",
  "./hatirlatma/__next.hatirlatma.__PAGE__.txt",
  "./yedek/index.txt",
  "./yedek/__next._tree.txt",
  "./yedek/__next._full.txt",
  "./yedek/__next.yedek.__PAGE__.txt",
  "./kullanim/index.txt",
  "./kullanim/__next._tree.txt",
  "./kullanim/__next._full.txt",
  "./kullanim/__next.kullanim.__PAGE__.txt",
];

// Extracts same-origin `/_next/static/...` URLs (JS chunks, CSS, woff2 fonts)
// referenced inside the pre-cached HTML documents so they are also warm before
// the phone goes offline.
function statikVarlikYollariniCikar(htmlMetni) {
  const eslesmeler =
    htmlMetni.match(/(?:\/[^\s"'\\()]*)?\/_next\/static\/[^\s"'\\()]+/g) || [];
  return Array.from(new Set(eslesmeler));
}

async function istegeBagliOnbellekle(onbellek, yol) {
  try {
    const yanit = await fetch(yol);
    if (yanit.ok) {
      await onbellek.put(yol, yanit);
    }
  } catch {
    // Ignore optional pre-cache misses so install still succeeds.
  }
}

self.addEventListener("install", (olay) => {
  olay.waitUntil(
    (async () => {
      const onbellek = await caches.open(ONBELLEK_ADI);
      await onbellek.addAll(ONBELLEK_SAYFALARI);

      const statikYollar = new Set(EK_ONBELLEK_DOSYALARI);
      for (const sayfa of ONBELLEK_SAYFALARI) {
        const kayitli = await onbellek.match(sayfa);
        if (!kayitli) continue;
        const metin = await kayitli.clone().text();
        for (const yol of statikVarlikYollariniCikar(metin)) {
          statikYollar.add(yol);
        }
      }

      await Promise.allSettled(
        Array.from(statikYollar, (yol) => istegeBagliOnbellekle(onbellek, yol))
      );

      await self.skipWaiting();
    })()
  );
});

self.addEventListener("activate", (olay) => {
  olay.waitUntil(
    (async () => {
      const anahtarlar = await caches.keys();
      await Promise.all(
        anahtarlar
          .filter((ad) => ad !== ONBELLEK_ADI)
          .map((ad) => caches.delete(ad))
      );
      await self.clients.claim();
    })()
  );
});

function statikVarlikMi(pathname) {
  return (
    pathname.includes("/_next/static/") ||
    pathname.includes("/icons/") ||
    pathname.endsWith("/manifest.webmanifest") ||
    /\.(?:woff2?|ttf|otf|png|svg|ico|webp|css|js)$/i.test(pathname)
  );
}

function rscPayloadMi(pathname) {
  return pathname.endsWith(".txt");
}

// Navigation strategy: network-first, falling back to the cached page without
// the query string (`ignoreSearch`) so `/arac/detay/?plaka=...` works offline.
async function gezinmeYaniti(istek) {
  const onbellek = await caches.open(ONBELLEK_ADI);
  const sadeUrl = new URL(istek.url);
  sadeUrl.search = "";
  sadeUrl.hash = "";
  const ekSlasliHref = sadeUrl.pathname.endsWith("/")
    ? sadeUrl.href
    : `${sadeUrl.href}/`;

  try {
    const agYaniti = await fetch(istek);
    if (agYaniti.ok) {
      await onbellek.put(sadeUrl.href, agYaniti.clone());
    }
    return agYaniti;
  } catch {
    const kayitli =
      (await onbellek.match(sadeUrl.href)) ||
      (await onbellek.match(ekSlasliHref)) ||
      (await onbellek.match(istek, { ignoreSearch: true })) ||
      (await onbellek.match(new URL("./", self.registration.scope).href));
    if (kayitli) return kayitli;
    throw new Error("Çevrimdışı ve önbellekte sayfa bulunamadı.");
  }
}

// Cache-first strategy for same-origin static assets and `.txt` RSC payloads.
async function onbellekOncelikliYanit(istek, sorguyuYoksay = false) {
  const onbellek = await caches.open(ONBELLEK_ADI);
  const kayitli = sorguyuYoksay
    ? await onbellek.match(istek, { ignoreSearch: true })
    : await onbellek.match(istek);
  if (kayitli) return kayitli;

  try {
    const agYaniti = await fetch(istek);
    if (agYaniti.ok) {
      const anahtarUrl = new URL(istek.url);
      if (sorguyuYoksay) {
        anahtarUrl.search = "";
        anahtarUrl.hash = "";
        await onbellek.put(anahtarUrl.href, agYaniti.clone());
      } else {
        await onbellek.put(istek, agYaniti.clone());
      }
    }
    return agYaniti;
  } catch (hata) {
    const yedek = await onbellek.match(istek, { ignoreSearch: true });
    if (yedek) return yedek;
    throw hata;
  }
}

self.addEventListener("fetch", (olay) => {
  const istek = olay.request;
  if (istek.method !== "GET") return;

  const url = new URL(istek.url);
  if (url.origin !== self.location.origin) return;

  if (istek.mode === "navigate") {
    olay.respondWith(gezinmeYaniti(istek));
    return;
  }

  if (statikVarlikMi(url.pathname)) {
    olay.respondWith(onbellekOncelikliYanit(istek, false));
    return;
  }

  if (rscPayloadMi(url.pathname)) {
    olay.respondWith(onbellekOncelikliYanit(istek, true));
    return;
  }

  // Any other same-origin GET request: cache successful responses as fetched
  // and serve from cache when offline.
  olay.respondWith(onbellekOncelikliYanit(istek, true));
});
